#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Inserisci il numero di righe per il triangolo: ";
    cin >> n;

    // Ciclo per stampare il triangolo di asterischi
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            cout << "*";
        }
        cout << endl;
    }

    cout << endl;
    system("pause");
}
